begin;

-- Whole-food ("clean") meal suggestions: minimally processed carbohydrate sources
-- (fruit, rice, potatoes, oats, quinoa) with lean proteins and vegetables. Every
-- meal was scored with the app's own ranking before being added, and every
-- ingredient maps to an existing verified food.

with recipes as (
  select * from jsonb_to_recordset($pre$[{"slug":"strictly-clean-rice-cake-stack-with-banana-and-honey","name":"Rice Cake Stack with Banana and Honey","description":"Rice cakes stacked with banana and a drizzle of honey for a short window.","ingredients":[{"foodId":"rice-cakes","grams":36},{"foodId":"banana","grams":118},{"foodId":"honey","grams":15}],"instructions":["Top the rice cakes with sliced banana.","Drizzle with honey."],"prep":3,"ideal":45,"low":30,"high":60,"minimum":30,"tags":["halal","vegetarian","vegan","dairy-free","gluten-free"],"allergens":[]},{"slug":"strictly-clean-dates-and-grapes-fruit-plate","name":"Dates and Grapes Fruit Plate","description":"Medjool dates and grapes: quick, simple fruit carbohydrate.","ingredients":[{"foodId":"dates","grams":48},{"foodId":"grapes","grams":151}],"instructions":["Pit the dates.","Serve with a cup of grapes."],"prep":2,"ideal":40,"low":25,"high":55,"minimum":30,"tags":["halal","vegetarian","vegan","dairy-free","gluten-free"],"allergens":[]},{"slug":"strictly-clean-pineapple-mango-honey-bowl","name":"Pineapple Mango Honey Bowl","description":"Fresh pineapple and mango with a little honey.","ingredients":[{"foodId":"pineapple","grams":165},{"foodId":"mango","grams":120},{"foodId":"honey","grams":12}],"instructions":["Cube the pineapple and mango.","Toss with honey."],"prep":5,"ideal":45,"low":30,"high":60,"minimum":30,"tags":["halal","vegetarian","vegan","dairy-free","gluten-free"],"allergens":[]},{"slug":"strictly-clean-applesauce-banana-and-raisins","name":"Applesauce, Banana and Raisins","description":"Unsweetened applesauce with banana and raisins.","ingredients":[{"foodId":"applesauce","grams":122},{"foodId":"banana","grams":118},{"foodId":"raisins","grams":20}],"instructions":["Spoon the applesauce into a bowl.","Add sliced banana and raisins."],"prep":3,"ideal":45,"low":30,"high":60,"minimum":30,"tags":["halal","vegetarian","vegan","dairy-free","gluten-free"],"allergens":[]},{"slug":"strictly-clean-jasmine-rice-and-mango-bowl","name":"Jasmine Rice and Mango Bowl","description":"Warm jasmine rice with mango and a touch of honey.","ingredients":[{"foodId":"jasmine-rice","grams":200},{"foodId":"mango","grams":120},{"foodId":"honey","grams":12}],"instructions":["Warm the rice.","Top with diced mango and honey."],"prep":10,"ideal":80,"low":65,"high":95,"minimum":45,"tags":["halal","vegetarian","vegan","dairy-free","gluten-free"],"allergens":[]},{"slug":"strictly-clean-sourdough-banana-honey-toast","name":"Sourdough Banana Honey Toast","description":"Toasted sourdough with banana and honey.","ingredients":[{"foodId":"sourdough","grams":76},{"foodId":"banana","grams":118},{"foodId":"honey","grams":15}],"instructions":["Toast the sourdough.","Top with sliced banana and honey."],"prep":5,"ideal":75,"low":60,"high":90,"minimum":30,"tags":["halal","vegetarian","vegan","dairy-free"],"allergens":["gluten"]},{"slug":"strictly-clean-greek-yogurt-berry-honey-bowl","name":"Greek Yogurt Berry Honey Bowl","description":"Greek yogurt with blueberries, strawberries, and honey.","ingredients":[{"foodId":"greek-yogurt","grams":170},{"foodId":"strictly-blueberries","grams":100},{"foodId":"strictly-strawberries","grams":100},{"foodId":"honey","grams":20}],"instructions":["Add yogurt to a bowl.","Top with the berries and honey."],"prep":4,"ideal":90,"low":75,"high":105,"minimum":30,"tags":["halal","vegetarian","gluten-free"],"allergens":["dairy"]},{"slug":"strictly-clean-cream-of-rice-with-peach-and-maple","name":"Cream of Rice with Peach and Maple","description":"Smooth cream of rice with peach and maple syrup.","ingredients":[{"foodId":"strictly-cooked-cream-of-rice","grams":240},{"foodId":"strictly-peach","grams":140},{"foodId":"maple-syrup","grams":15}],"instructions":["Cook the cream of rice until smooth.","Top with sliced peach and maple syrup."],"prep":8,"ideal":75,"low":60,"high":90,"minimum":30,"tags":["halal","vegetarian","vegan","dairy-free","gluten-free"],"allergens":[]},{"slug":"strictly-clean-overnight-oats-with-berries-and-banana","name":"Overnight Oats with Berries and Banana","description":"Overnight oats with blueberries and banana.","ingredients":[{"foodId":"strictly-overnight-oats","grams":170},{"foodId":"strictly-blueberries","grams":100},{"foodId":"banana","grams":60}],"instructions":["Prepare the oats the night before.","Top with blueberries and banana."],"prep":5,"ideal":120,"low":105,"high":135,"minimum":45,"tags":["halal","vegetarian","vegan","dairy-free"],"allergens":["gluten"]},{"slug":"strictly-clean-quinoa-mango-yogurt-breakfast-bowl","name":"Quinoa Mango Yogurt Breakfast Bowl","description":"Quinoa with mango, Greek yogurt, and honey.","ingredients":[{"foodId":"quinoa","grams":185},{"foodId":"mango","grams":120},{"foodId":"greek-yogurt","grams":100},{"foodId":"honey","grams":15}],"instructions":["Warm the quinoa.","Top with yogurt, mango, and honey."],"prep":10,"ideal":140,"low":125,"high":155,"minimum":60,"tags":["halal","vegetarian","gluten-free"],"allergens":["dairy"]},{"slug":"strictly-clean-chicken-sweet-potato-and-spinach-plate","name":"Chicken, Sweet Potato and Spinach Plate","description":"Chicken breast with sweet potato and wilted spinach.","ingredients":[{"foodId":"chicken","grams":90},{"foodId":"sweet-potato","grams":220},{"foodId":"spinach","grams":60}],"instructions":["Roast or microwave the sweet potato.","Serve with chicken and spinach."],"prep":20,"ideal":160,"low":145,"high":175,"minimum":60,"tags":["halal","dairy-free","gluten-free"],"allergens":[]},{"slug":"strictly-clean-salmon-rice-and-pineapple-bowl","name":"Salmon Rice and Pineapple Bowl","description":"Salmon over white rice with pineapple.","ingredients":[{"foodId":"salmon","grams":85},{"foodId":"white-rice","grams":220},{"foodId":"pineapple","grams":100}],"instructions":["Warm the rice.","Top with cooked salmon and pineapple."],"prep":18,"ideal":150,"low":135,"high":165,"minimum":60,"tags":["halal","pescatarian","dairy-free","gluten-free"],"allergens":["fish"]},{"slug":"strictly-clean-turkey-quinoa-bowl-with-orange","name":"Turkey Quinoa Bowl with Orange","description":"Turkey breast and quinoa with a fresh orange.","ingredients":[{"foodId":"turkey-breast","grams":90},{"foodId":"quinoa","grams":185},{"foodId":"orange","grams":131}],"instructions":["Warm the quinoa and turkey.","Serve with an orange on the side."],"prep":15,"ideal":150,"low":135,"high":165,"minimum":60,"tags":["halal","dairy-free","gluten-free"],"allergens":[]},{"slug":"strictly-clean-tofu-jasmine-rice-and-broccoli-bowl","name":"Tofu Jasmine Rice and Broccoli Bowl","description":"Seared tofu with jasmine rice and broccoli.","ingredients":[{"foodId":"firm-tofu","grams":100},{"foodId":"jasmine-rice","grams":220},{"foodId":"broccoli","grams":80}],"instructions":["Sear the tofu.","Serve over rice with steamed broccoli."],"prep":18,"ideal":140,"low":125,"high":155,"minimum":60,"tags":["halal","vegetarian","vegan","dairy-free","gluten-free"],"allergens":["soy"]},{"slug":"strictly-clean-egg-potato-and-orange-breakfast","name":"Egg, Potato and Orange Breakfast","description":"Eggs with boiled potatoes and an orange.","ingredients":[{"foodId":"whole-eggs","grams":100},{"foodId":"potato","grams":220},{"foodId":"orange","grams":131}],"instructions":["Boil the potatoes and cook the eggs.","Serve with an orange."],"prep":15,"ideal":150,"low":135,"high":165,"minimum":60,"tags":["halal","vegetarian","dairy-free","gluten-free"],"allergens":["eggs"]},{"slug":"strictly-clean-chicken-rice-noodle-veggie-bowl","name":"Chicken Rice Noodle Veggie Bowl","description":"Chicken with rice noodles and mixed vegetables.","ingredients":[{"foodId":"chicken","grams":85},{"foodId":"strictly-cooked-rice-noodles","grams":260},{"foodId":"mixed-vegetables","grams":80}],"instructions":["Cook the rice noodles.","Toss with chicken and vegetables."],"prep":15,"ideal":140,"low":125,"high":155,"minimum":60,"tags":["halal","dairy-free","gluten-free"],"allergens":[]},{"slug":"strictly-clean-baked-potato-with-cottage-cheese-and-pineapple","name":"Baked Potato with Cottage Cheese and Pineapple","description":"A baked potato with cottage cheese and pineapple.","ingredients":[{"foodId":"potato","grams":250},{"foodId":"cottage-cheese","grams":120},{"foodId":"pineapple","grams":100}],"instructions":["Bake or microwave the potato.","Top with cottage cheese; serve pineapple alongside."],"prep":12,"ideal":130,"low":115,"high":145,"minimum":45,"tags":["halal","vegetarian","gluten-free"],"allergens":["dairy"]},{"slug":"strictly-clean-tuna-rice-bowl-with-spinach","name":"Tuna Rice Bowl with Spinach","description":"Tuna over white rice with spinach and salsa.","ingredients":[{"foodId":"tuna","grams":80},{"foodId":"white-rice","grams":220},{"foodId":"spinach","grams":50},{"foodId":"salsa","grams":40}],"instructions":["Warm the rice.","Top with tuna, spinach, and salsa."],"prep":10,"ideal":140,"low":125,"high":155,"minimum":60,"tags":["halal","pescatarian","dairy-free","gluten-free"],"allergens":["fish"]},{"slug":"strictly-clean-brown-rice-lentil-and-spinach-bowl","name":"Brown Rice, Lentil and Spinach Bowl","description":"Brown rice with lentils and spinach for longer windows.","ingredients":[{"foodId":"brown-rice","grams":195},{"foodId":"lentils","grams":100},{"foodId":"spinach","grams":60}],"instructions":["Warm the rice and lentils.","Stir in spinach until wilted."],"prep":20,"ideal":180,"low":165,"high":195,"minimum":75,"tags":["halal","vegetarian","vegan","dairy-free","gluten-free"],"allergens":[]},{"slug":"strictly-clean-sweet-potato-egg-and-apple-plate","name":"Sweet Potato, Egg and Apple Plate","description":"Sweet potato with eggs and a crisp apple.","ingredients":[{"foodId":"sweet-potato","grams":200},{"foodId":"whole-eggs","grams":100},{"foodId":"apple","grams":150}],"instructions":["Cook the sweet potato and eggs.","Serve with a sliced apple."],"prep":18,"ideal":160,"low":145,"high":175,"minimum":60,"tags":["halal","vegetarian","dairy-free","gluten-free"],"allergens":["eggs"]},{"slug":"strictly-clean-oatmeal-with-banana-and-peanut-butter","name":"Oatmeal with Banana and Peanut Butter","description":"Rolled oats with banana and a spoon of peanut butter.","ingredients":[{"foodId":"oats","grams":260},{"foodId":"banana","grams":118},{"foodId":"peanut-butter","grams":16}],"instructions":["Cook the oats.","Top with banana and peanut butter."],"prep":8,"ideal":160,"low":145,"high":175,"minimum":60,"tags":["halal","vegetarian","vegan","dairy-free"],"allergens":["gluten","peanuts"]}]$pre$::jsonb)
    as r(slug text,name text,description text,ingredients jsonb,instructions jsonb,prep integer,ideal integer,low integer,high integer,minimum integer,tags jsonb,allergens jsonb)
)
insert into public.meal_templates (
  slug,name,description,prep_minutes,instructions,dietary_tags,allergens,activity_types,
  ideal_timing_minutes,timing_low_minutes,timing_high_minutes,min_workout_minutes,
  ingredient_blueprint,is_verified,purpose
)
select slug,name,description,prep,
  array(select jsonb_array_elements_text(instructions)),
  array(select jsonb_array_elements_text(tags)),
  array(select jsonb_array_elements_text(allergens)),
  array['running','trail_running','cycling','indoor_cycling','swimming','rowing','triathlon','strength','strength_training','bodybuilding','crossfit','hyrox','soccer','basketball','general_cardio','mixed_training']::text[],
  ideal,low,high,minimum,ingredients,true,'pre_workout'
from recipes
on conflict (slug) do update set
  name=excluded.name,description=excluded.description,prep_minutes=excluded.prep_minutes,
  instructions=excluded.instructions,dietary_tags=excluded.dietary_tags,allergens=excluded.allergens,
  activity_types=excluded.activity_types,ideal_timing_minutes=excluded.ideal_timing_minutes,
  timing_low_minutes=excluded.timing_low_minutes,timing_high_minutes=excluded.timing_high_minutes,
  min_workout_minutes=excluded.min_workout_minutes,ingredient_blueprint=excluded.ingredient_blueprint,
  is_verified=true,purpose='pre_workout',updated_at=now();

with recipes as (
  select * from jsonb_to_recordset($post$[{"slug":"strictly-post-clean-chicken-sweet-potato-broccoli-plate","name":"Chicken Sweet Potato Broccoli Plate","description":"Chicken breast, sweet potato, broccoli, and olive oil.","ingredients":[{"foodId":"chicken","grams":113,"role":"protein","scalable":true,"minGrams":60,"maxGrams":227,"incrementGrams":14},{"foodId":"sweet-potato","grams":300,"role":"carb","scalable":true,"minGrams":150,"maxGrams":600,"incrementGrams":50},{"foodId":"broccoli","grams":100,"role":"produce"},{"foodId":"olive-oil","grams":8,"role":"fat"}],"instructions":["Roast the sweet potato and broccoli.","Serve with chicken and a drizzle of olive oil."],"prep":25,"difficulty":"easy","cuisine":"Plate","mealType":"dinner","tags":["halal","dairy-free","gluten-free"],"allergens":[],"categories":["post_workout_standard","post_workout_high_demand"],"carb":"sweet-potato","protein":"chicken"},{"slug":"strictly-post-clean-salmon-quinoa-avocado-bowl","name":"Salmon Quinoa Avocado Bowl","description":"Salmon with quinoa, spinach, and avocado.","ingredients":[{"foodId":"salmon","grams":113,"role":"protein","scalable":true,"minGrams":70,"maxGrams":200,"incrementGrams":14},{"foodId":"quinoa","grams":280,"role":"carb","scalable":true,"minGrams":150,"maxGrams":560,"incrementGrams":45},{"foodId":"spinach","grams":60,"role":"produce"},{"foodId":"avocado","grams":30,"role":"fat"}],"instructions":["Warm the quinoa.","Top with salmon, spinach, and sliced avocado."],"prep":25,"difficulty":"moderate","cuisine":"Mediterranean","mealType":"dinner","tags":["halal","pescatarian","dairy-free","gluten-free"],"allergens":["fish"],"categories":["post_workout_standard","post_workout_high_demand"],"carb":"quinoa","protein":"salmon"},{"slug":"strictly-post-clean-turkey-brown-rice-salsa-bowl","name":"Turkey Brown Rice Salsa Bowl","description":"Turkey with brown rice, vegetables, and salsa.","ingredients":[{"foodId":"turkey-breast","grams":113,"role":"protein","scalable":true,"minGrams":60,"maxGrams":227,"incrementGrams":14},{"foodId":"brown-rice","grams":300,"role":"carb","scalable":true,"minGrams":150,"maxGrams":600,"incrementGrams":50},{"foodId":"mixed-vegetables","grams":120,"role":"produce"},{"foodId":"salsa","grams":60,"role":"produce"}],"instructions":["Warm the rice and vegetables.","Add turkey and top with salsa."],"prep":20,"difficulty":"easy","cuisine":"Mexican-inspired","mealType":"lunch","tags":["halal","dairy-free","gluten-free"],"allergens":[],"categories":["post_workout_standard","post_workout_high_demand"],"carb":"brown-rice","protein":"turkey-breast"},{"slug":"strictly-post-clean-tofu-jasmine-rice-broccoli-stir-fry","name":"Tofu Jasmine Rice Broccoli Stir-Fry","description":"Seared tofu with jasmine rice and broccoli.","ingredients":[{"foodId":"firm-tofu","grams":170,"role":"protein","scalable":true,"minGrams":100,"maxGrams":300,"incrementGrams":20},{"foodId":"jasmine-rice","grams":280,"role":"carb","scalable":true,"minGrams":150,"maxGrams":560,"incrementGrams":50},{"foodId":"broccoli","grams":120,"role":"produce"},{"foodId":"olive-oil","grams":8,"role":"fat"}],"instructions":["Sear the tofu in oil.","Stir-fry with broccoli and serve over rice."],"prep":22,"difficulty":"moderate","cuisine":"Asian-inspired","mealType":"dinner","tags":["halal","vegetarian","vegan","dairy-free","gluten-free"],"allergens":["soy"],"categories":["post_workout_standard","post_workout_high_demand"],"carb":"jasmine-rice","protein":"firm-tofu"},{"slug":"strictly-post-clean-egg-potato-and-spinach-breakfast-plate","name":"Egg, Potato and Spinach Breakfast Plate","description":"Eggs with boiled potatoes and spinach.","ingredients":[{"foodId":"whole-eggs","grams":150,"role":"protein","scalable":true,"minGrams":100,"maxGrams":250,"incrementGrams":50},{"foodId":"potato","grams":300,"role":"carb","scalable":true,"minGrams":150,"maxGrams":500,"incrementGrams":50},{"foodId":"spinach","grams":60,"role":"produce"}],"instructions":["Boil or roast the potatoes.","Cook the eggs with spinach."],"prep":18,"difficulty":"easy","cuisine":"Breakfast","mealType":"breakfast","tags":["halal","vegetarian","dairy-free","gluten-free"],"allergens":["eggs"],"categories":["post_workout_standard","post_workout_light"],"carb":"potato","protein":"whole-eggs"},{"slug":"strictly-post-clean-greek-yogurt-berry-oat-recovery-bowl","name":"Greek Yogurt Berry Oat Recovery Bowl","description":"Greek yogurt over oats with blueberries and honey.","ingredients":[{"foodId":"greek-yogurt","grams":250,"role":"protein","scalable":true,"minGrams":170,"maxGrams":400,"incrementGrams":50},{"foodId":"oats","grams":260,"role":"carb","scalable":true,"minGrams":150,"maxGrams":450,"incrementGrams":50},{"foodId":"strictly-blueberries","grams":100,"role":"produce"},{"foodId":"honey","grams":15,"role":"carb"}],"instructions":["Cook the oats.","Top with yogurt, blueberries, and honey."],"prep":8,"difficulty":"easy","cuisine":"Breakfast","mealType":"breakfast","tags":["halal","vegetarian"],"allergens":["gluten","dairy"],"categories":["post_workout_light","post_workout_standard","post_workout_rapid_recovery"],"carb":"oats","protein":"greek-yogurt"},{"slug":"strictly-post-clean-tuna-white-rice-avocado-bowl","name":"Tuna White Rice Avocado Bowl","description":"Tuna over white rice with spinach and avocado.","ingredients":[{"foodId":"tuna","grams":100,"role":"protein","scalable":true,"minGrams":60,"maxGrams":180,"incrementGrams":20},{"foodId":"white-rice","grams":300,"role":"carb","scalable":true,"minGrams":150,"maxGrams":600,"incrementGrams":50},{"foodId":"spinach","grams":60,"role":"produce"},{"foodId":"avocado","grams":35,"role":"fat"}],"instructions":["Warm the rice.","Top with tuna, spinach, and avocado."],"prep":12,"difficulty":"easy","cuisine":"Bowl","mealType":"lunch","tags":["halal","pescatarian","dairy-free","gluten-free"],"allergens":["fish"],"categories":["post_workout_standard","post_workout_high_demand"],"carb":"white-rice","protein":"tuna"},{"slug":"strictly-post-clean-lentil-sweet-potato-spinach-bowl","name":"Lentil Sweet Potato Spinach Bowl","description":"Lentils with sweet potato and spinach.","ingredients":[{"foodId":"lentils","grams":220,"role":"protein","scalable":true,"minGrams":150,"maxGrams":340,"incrementGrams":40},{"foodId":"sweet-potato","grams":250,"role":"carb","scalable":true,"minGrams":120,"maxGrams":400,"incrementGrams":50},{"foodId":"spinach","grams":80,"role":"produce"},{"foodId":"olive-oil","grams":5,"role":"fat"}],"instructions":["Roast the sweet potato.","Warm the lentils with spinach and finish with olive oil."],"prep":25,"difficulty":"easy","cuisine":"Bowl","mealType":"dinner","tags":["halal","vegetarian","vegan","dairy-free","gluten-free"],"allergens":[],"categories":["post_workout_standard","post_workout_light"],"carb":"sweet-potato","protein":"lentils"},{"slug":"strictly-post-clean-sirloin-potato-and-broccoli-plate","name":"Sirloin, Potato and Broccoli Plate","description":"Lean sirloin with potatoes and broccoli.","ingredients":[{"foodId":"sirloin-steak","grams":113,"role":"protein","scalable":true,"minGrams":60,"maxGrams":227,"incrementGrams":14},{"foodId":"potato","grams":350,"role":"carb","scalable":true,"minGrams":150,"maxGrams":700,"incrementGrams":50},{"foodId":"broccoli","grams":120,"role":"produce"}],"instructions":["Cook the sirloin to your liking.","Serve with potatoes and broccoli."],"prep":28,"difficulty":"moderate","cuisine":"American","mealType":"dinner","tags":["halal","dairy-free","gluten-free"],"allergens":[],"categories":["post_workout_standard","post_workout_high_demand"],"carb":"potato","protein":"sirloin-steak"},{"slug":"strictly-post-clean-cottage-cheese-banana-and-rice-cakes","name":"Cottage Cheese, Banana and Rice Cakes","description":"Cottage cheese with rice cakes, banana, and honey.","ingredients":[{"foodId":"cottage-cheese","grams":250,"role":"protein","scalable":true,"minGrams":180,"maxGrams":350,"incrementGrams":50},{"foodId":"rice-cakes","grams":36,"role":"carb","scalable":true,"minGrams":18,"maxGrams":90,"incrementGrams":9},{"foodId":"banana","grams":118,"role":"produce"},{"foodId":"honey","grams":15,"role":"carb"}],"instructions":["Spread cottage cheese on the rice cakes.","Top with banana and honey."],"prep":5,"difficulty":"easy","cuisine":"Plate","mealType":"light_meal","tags":["halal","vegetarian","gluten-free"],"allergens":["dairy"],"categories":["post_workout_light","post_workout_rapid_recovery"],"carb":"rice-cakes","protein":"cottage-cheese"}]$post$::jsonb)
    as r(slug text,name text,description text,ingredients jsonb,instructions jsonb,prep integer,difficulty text,cuisine text,"mealType" text,tags jsonb,allergens jsonb,categories jsonb,carb text,protein text)
)
insert into public.meal_templates (
  slug,name,description,prep_minutes,instructions,dietary_tags,allergens,activity_types,
  ideal_timing_minutes,timing_low_minutes,timing_high_minutes,min_workout_minutes,
  ingredient_blueprint,is_verified,purpose,recovery_categories,cuisine_category,meal_type,
  preparation_difficulty,is_portion_scalable,primary_carb_food_id,primary_protein_food_id
)
select slug,name,description,prep,
  array(select jsonb_array_elements_text(instructions)),
  array(select jsonb_array_elements_text(tags)),
  array(select jsonb_array_elements_text(allergens)),
  array['running','trail_running','cycling','indoor_cycling','mountain_biking','swimming','rowing','triathlon','ironman_70_3','ironman','strength','strength_training','bodybuilding','powerlifting','crossfit','hyrox','hiit','soccer','basketball','general_cardio','mixed_training','endurance']::text[],
  60,30,120,0,ingredients,true,'post_workout',
  array(select jsonb_array_elements_text(categories)),cuisine,"mealType",difficulty,true,carb,protein
from recipes
on conflict (slug) do update set
  name=excluded.name,description=excluded.description,prep_minutes=excluded.prep_minutes,
  instructions=excluded.instructions,dietary_tags=excluded.dietary_tags,allergens=excluded.allergens,
  activity_types=excluded.activity_types,ingredient_blueprint=excluded.ingredient_blueprint,
  is_verified=true,purpose='post_workout',recovery_categories=excluded.recovery_categories,
  cuisine_category=excluded.cuisine_category,meal_type=excluded.meal_type,
  preparation_difficulty=excluded.preparation_difficulty,is_portion_scalable=true,
  primary_carb_food_id=excluded.primary_carb_food_id,
  primary_protein_food_id=excluded.primary_protein_food_id,updated_at=now();

delete from public.meal_template_items
where template_id in (select id from public.meal_templates where slug in ('strictly-clean-rice-cake-stack-with-banana-and-honey','strictly-clean-dates-and-grapes-fruit-plate','strictly-clean-pineapple-mango-honey-bowl','strictly-clean-applesauce-banana-and-raisins','strictly-clean-jasmine-rice-and-mango-bowl','strictly-clean-sourdough-banana-honey-toast','strictly-clean-greek-yogurt-berry-honey-bowl','strictly-clean-cream-of-rice-with-peach-and-maple','strictly-clean-overnight-oats-with-berries-and-banana','strictly-clean-quinoa-mango-yogurt-breakfast-bowl','strictly-clean-chicken-sweet-potato-and-spinach-plate','strictly-clean-salmon-rice-and-pineapple-bowl','strictly-clean-turkey-quinoa-bowl-with-orange','strictly-clean-tofu-jasmine-rice-and-broccoli-bowl','strictly-clean-egg-potato-and-orange-breakfast','strictly-clean-chicken-rice-noodle-veggie-bowl','strictly-clean-baked-potato-with-cottage-cheese-and-pineapple','strictly-clean-tuna-rice-bowl-with-spinach','strictly-clean-brown-rice-lentil-and-spinach-bowl','strictly-clean-sweet-potato-egg-and-apple-plate','strictly-clean-oatmeal-with-banana-and-peanut-butter','strictly-post-clean-chicken-sweet-potato-broccoli-plate','strictly-post-clean-salmon-quinoa-avocado-bowl','strictly-post-clean-turkey-brown-rice-salsa-bowl','strictly-post-clean-tofu-jasmine-rice-broccoli-stir-fry','strictly-post-clean-egg-potato-and-spinach-breakfast-plate','strictly-post-clean-greek-yogurt-berry-oat-recovery-bowl','strictly-post-clean-tuna-white-rice-avocado-bowl','strictly-post-clean-lentil-sweet-potato-spinach-bowl','strictly-post-clean-sirloin-potato-and-broccoli-plate','strictly-post-clean-cottage-cheese-banana-and-rice-cakes'));

insert into public.meal_template_items (
  template_id,position,food_id,food_name_snapshot,grams,serving_note,is_scalable
)
select mt.id, ingredient.ordinality::smallint, f.id,
  coalesce(f.name, ingredient.value->>'foodId'),
  (ingredient.value->>'grams')::numeric,
  ingredient.value->>'role',
  coalesce((ingredient.value->>'scalable')::boolean, mt.purpose='pre_workout')
from public.meal_templates mt
cross join lateral jsonb_array_elements(mt.ingredient_blueprint) with ordinality as ingredient(value,ordinality)
left join public.foods f on f.source_id='strictly' and f.source_product_id in (
  'starter:'||(ingredient.value->>'foodId'),
  'library:'||regexp_replace(ingredient.value->>'foodId','^strictly-',''),
  'recovery:'||(ingredient.value->>'foodId')
)
where mt.slug in ('strictly-clean-rice-cake-stack-with-banana-and-honey','strictly-clean-dates-and-grapes-fruit-plate','strictly-clean-pineapple-mango-honey-bowl','strictly-clean-applesauce-banana-and-raisins','strictly-clean-jasmine-rice-and-mango-bowl','strictly-clean-sourdough-banana-honey-toast','strictly-clean-greek-yogurt-berry-honey-bowl','strictly-clean-cream-of-rice-with-peach-and-maple','strictly-clean-overnight-oats-with-berries-and-banana','strictly-clean-quinoa-mango-yogurt-breakfast-bowl','strictly-clean-chicken-sweet-potato-and-spinach-plate','strictly-clean-salmon-rice-and-pineapple-bowl','strictly-clean-turkey-quinoa-bowl-with-orange','strictly-clean-tofu-jasmine-rice-and-broccoli-bowl','strictly-clean-egg-potato-and-orange-breakfast','strictly-clean-chicken-rice-noodle-veggie-bowl','strictly-clean-baked-potato-with-cottage-cheese-and-pineapple','strictly-clean-tuna-rice-bowl-with-spinach','strictly-clean-brown-rice-lentil-and-spinach-bowl','strictly-clean-sweet-potato-egg-and-apple-plate','strictly-clean-oatmeal-with-banana-and-peanut-butter','strictly-post-clean-chicken-sweet-potato-broccoli-plate','strictly-post-clean-salmon-quinoa-avocado-bowl','strictly-post-clean-turkey-brown-rice-salsa-bowl','strictly-post-clean-tofu-jasmine-rice-broccoli-stir-fry','strictly-post-clean-egg-potato-and-spinach-breakfast-plate','strictly-post-clean-greek-yogurt-berry-oat-recovery-bowl','strictly-post-clean-tuna-white-rice-avocado-bowl','strictly-post-clean-lentil-sweet-potato-spinach-bowl','strictly-post-clean-sirloin-potato-and-broccoli-plate','strictly-post-clean-cottage-cheese-banana-and-rice-cakes');

with totals as (
  select mti.template_id,
    sum(f.calories_per_100g*mti.grams/100) calories,
    sum(f.carbs_per_100g*mti.grams/100) carbs,
    sum(f.protein_per_100g*mti.grams/100) protein,
    sum(f.fat_per_100g*mti.grams/100) fat,
    sum(f.fiber_per_100g*mti.grams/100) fiber,
    sum(case when f.carb_speed_tier_id='fast' then f.carbs_per_100g*mti.grams/100 else 0 end) fast,
    sum(case when f.carb_speed_tier_id='medium' then f.carbs_per_100g*mti.grams/100 else 0 end) medium,
    sum(case when f.carb_speed_tier_id='slow' then f.carbs_per_100g*mti.grams/100 else 0 end) slow
  from public.meal_template_items mti
  join public.foods f on f.id=mti.food_id
  join public.meal_templates mt on mt.id=mti.template_id
  where mt.slug in ('strictly-clean-rice-cake-stack-with-banana-and-honey','strictly-clean-dates-and-grapes-fruit-plate','strictly-clean-pineapple-mango-honey-bowl','strictly-clean-applesauce-banana-and-raisins','strictly-clean-jasmine-rice-and-mango-bowl','strictly-clean-sourdough-banana-honey-toast','strictly-clean-greek-yogurt-berry-honey-bowl','strictly-clean-cream-of-rice-with-peach-and-maple','strictly-clean-overnight-oats-with-berries-and-banana','strictly-clean-quinoa-mango-yogurt-breakfast-bowl','strictly-clean-chicken-sweet-potato-and-spinach-plate','strictly-clean-salmon-rice-and-pineapple-bowl','strictly-clean-turkey-quinoa-bowl-with-orange','strictly-clean-tofu-jasmine-rice-and-broccoli-bowl','strictly-clean-egg-potato-and-orange-breakfast','strictly-clean-chicken-rice-noodle-veggie-bowl','strictly-clean-baked-potato-with-cottage-cheese-and-pineapple','strictly-clean-tuna-rice-bowl-with-spinach','strictly-clean-brown-rice-lentil-and-spinach-bowl','strictly-clean-sweet-potato-egg-and-apple-plate','strictly-clean-oatmeal-with-banana-and-peanut-butter','strictly-post-clean-chicken-sweet-potato-broccoli-plate','strictly-post-clean-salmon-quinoa-avocado-bowl','strictly-post-clean-turkey-brown-rice-salsa-bowl','strictly-post-clean-tofu-jasmine-rice-broccoli-stir-fry','strictly-post-clean-egg-potato-and-spinach-breakfast-plate','strictly-post-clean-greek-yogurt-berry-oat-recovery-bowl','strictly-post-clean-tuna-white-rice-avocado-bowl','strictly-post-clean-lentil-sweet-potato-spinach-bowl','strictly-post-clean-sirloin-potato-and-broccoli-plate','strictly-post-clean-cottage-cheese-banana-and-rice-cakes')
  group by mti.template_id
)
update public.meal_templates mt set
  calories=round(t.calories,2),carbs_g=round(t.carbs,2),protein_g=round(t.protein,2),
  fat_g=round(t.fat,2),fiber_g=round(t.fiber,2),fast_carbs_g=round(t.fast,2),
  medium_carbs_g=round(t.medium,2),slow_carbs_g=round(t.slow,2),updated_at=now()
from totals t where mt.id=t.template_id;

commit;
